import { useState, useEffect } from 'react'
import { ArrowLeft, ArrowRight } from 'lucide-react'
import { GENRES, genreTagline } from '../data/genres'
import { useCatalog } from '../lib/catalog-context'
import { byGenre } from '../lib/selectors'
import type { Genre } from '../types'
import { SeriesCard } from '../components/SeriesCard'
import { Button } from '../components/ui'
import { navigate } from '../lib/router'
import { cx, formatViews, genreHref } from '../lib/utils'
import { setSeo, buildGenreMeta } from '../lib/seo'

export default function GenreDetail({ name, page }: { name: string; page?: number }) {
  const { series: catalog, loading } = useCatalog()
  const genre = GENRES.find((g) => g.name.toLowerCase() === name.toLowerCase())?.name as Genre | undefined
  const [sort, setSort] = useState<'trending' | 'rating' | 'newest' | 'popular'>('trending')
  // /genres/:slug/page/:n views a 60-title window (mirrors the prerendered
  // pagination pages); page 1 = the canonical genre page itself
  const pageNum = page && page > 1 ? page : null

  // Unique per-genre metadata (title, description, canonical, JSON-LD)
  useEffect(() => {
    if (genre) setSeo(buildGenreMeta(genre, byGenre(catalog, genre).length))
  }, [genre, catalog.length])

  if (!genre) {
    return (
      <main className="mx-auto max-w-[1240px] px-4 py-24 text-center sm:px-6 lg:px-8">
        <h1 className="text-2xl font-extrabold">Unidentified Genre</h1>
        <p className="mt-2 text-ink-soft">This category doesn't exist in the directory.</p>
        <div className="mt-6">
          <Button onClick={() => navigate('/genres')}>Back to Genre Directory</Button>
        </div>
      </main>
    )
  }

  let list = byGenre(catalog, genre)
  if (sort === 'rating') list = [...list].sort((a, b) => b.rating - a.rating)
  if (sort === 'newest') list = [...list].sort((a, b) => +new Date(b.firstReleased) - +new Date(a.firstReleased))
  if (sort === 'popular') list = [...list].sort((a, b) => b.views - a.views)

  const totalViews = list.reduce((n, s) => n + s.views, 0)
  const ongoing = list.filter((s) => s.status === 'Ongoing').length
  const completed = list.filter((s) => s.status === 'Completed').length

  // Neighbouring genres for the footer strip
  const idx = GENRES.findIndex((g) => g.name === genre)
  const neighbours = [GENRES[(idx + 1) % GENRES.length], GENRES[(idx + 2) % GENRES.length], GENRES[(idx + 3) % GENRES.length]]

  return (
    <main className="animate-fade-up">
      {/* Banner */}
      <div
        className="border-b border-line"
        style={{
          background: `linear-gradient(115deg, hsl(${list[0]?.hue ?? 20} 30% 14%) 0%, hsl(${list[0]?.accentHue ?? 30} 28% 26%) 100%)`,
        }}
      >
        <div className="mx-auto max-w-[1240px] px-4 py-12 text-paper sm:px-6 lg:px-8">
          <button
            onClick={() => navigate('/genres')}
            className="mb-6 inline-flex items-center gap-1.5 text-sm font-semibold text-white/70 transition-colors hover:text-white"
          >
            <ArrowLeft width={16} height={16} /> Genre Directory
          </button>
          <div className="eyebrow text-accent">Explore Genre</div>
          <h1 className="mt-2 text-4xl font-extrabold tracking-tight sm:text-5xl">{genre}</h1>
          <p className="mt-3 max-w-xl text-white/70">{genreTagline(genre)}</p>
          <div className="mt-6 flex flex-wrap gap-x-6 gap-y-2 text-sm text-white/60">
            <span>
              <strong className="text-white">{loading ? '…' : list.length}</strong> series
            </span>
            <span>
              <strong className="text-white">{ongoing}</strong> ongoing
            </span>
            <span>
              <strong className="text-white">{completed}</strong> completed
            </span>
            <span>
              <strong className="text-white">{formatViews(totalViews)}</strong> total views
            </span>
          </div>
        </div>
      </div>

      <div className="mx-auto max-w-[1240px] px-4 py-10 sm:px-6 lg:px-8">
        {/* Sort bar */}
        <div className="mb-6 flex flex-wrap items-center justify-between gap-3">
          <div className="text-sm text-ink-faint">
            Popular in <strong className="text-ink">{genre}</strong>
          </div>
          <div className="flex gap-1.5">
            {(['trending', 'rating', 'newest', 'popular'] as const).map((k) => (
              <button
                key={k}
                onClick={() => setSort(k)}
                className={cx(
                  'rounded-full border px-3.5 py-1.5 text-xs font-semibold capitalize transition-colors',
                  sort === k
                    ? 'border-ink bg-ink text-paper'
                    : 'border-line-strong bg-paper text-ink-soft hover:border-ink hover:text-ink',
                )}
              >
                {k === 'trending' ? 'Trending' : k === 'rating' ? 'Highest Rated' : k === 'newest' ? 'Newest' : 'Most Popular'}
              </button>
            ))}
          </div>
        </div>

        {loading ? (
          <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
            {Array.from({ length: 10 }).map((_, i) => (
              <div key={i}>
                <div className="aspect-[3/4] animate-pulse rounded-[14px] bg-paper-3/60" />
                <div className="mt-3 h-4 w-3/4 animate-pulse rounded bg-paper-3/60" />
              </div>
            ))}
          </div>
        ) : list.length === 0 ? (
          <div className="rounded-[18px] border border-dashed border-line-strong bg-paper px-6 py-20 text-center">
            <div className="text-lg font-bold">No stories found</div>
            <p className="mt-2 text-sm text-ink-soft">
              No series are filed under this genre yet.
            </p>
          </div>
        ) : (
          <div className="grid grid-cols-2 gap-x-5 gap-y-8 sm:grid-cols-3 lg:grid-cols-5">
            {(pageNum ? list.slice((pageNum - 1) * 60, pageNum * 60) : list).map((s) => (
              <SeriesCard key={s.id} series={s} />
            ))}
          </div>
        )}

        {/* pagination strip — only on paged views */}
        {pageNum && (
          <div className="mt-10 flex items-center justify-between border-t border-line pt-6 text-sm">
            {pageNum > 1 ? (
              <button
                onClick={() =>
                  navigate(genreHref(genre) + (pageNum - 1 > 1 ? `/page/${pageNum - 1}` : ''))
                }
                className="font-semibold text-accent hover:underline"
              >
                ← Page {pageNum - 1}
              </button>
            ) : (
              <span />
            )}
            {pageNum * 60 < list.length ? (
              <button
                onClick={() => navigate(`${genreHref(genre)}/page/${pageNum + 1}`)}
                className="font-semibold text-accent hover:underline"
              >
                Page {pageNum + 1} →
              </button>
            ) : (
              <span />
            )}
          </div>
        )}

        {/* Related genres */}
        <section className="mt-16">
          <div className="eyebrow mb-4 text-accent">Keep Exploring</div>
          <div className="grid gap-3 sm:grid-cols-3">
            {neighbours.map((g) => (
              <a
                key={g.name}
                href={genreHref(g.name)}
                onClick={(e) => {
                  if (e.metaKey || e.ctrlKey) return
                  e.preventDefault()
                  navigate(genreHref(g.name))
                }}
                className="group flex items-center justify-between rounded-[14px] border border-line bg-paper p-4 transition-all hover:-translate-y-0.5 hover:shadow-md"
              >
                <div>
                  <div className="font-extrabold tracking-tight group-hover:text-accent">{g.name}</div>
                  <div className="mt-0.5 text-xs text-ink-faint">
                    {catalog.filter((s) => s.genres.includes(g.name)).length} titles
                  </div>
                </div>
                <ArrowRight width={18} height={18} className="text-ink-faint transition-all group-hover:translate-x-1 group-hover:text-accent" />
              </a>
            ))}
          </div>
        </section>
      </div>
    </main>
  )
}
